// Valida en el servidor y clasifica la urgencia por palabras clave.
// Reglas: ignora negaciones ("sin fiebre"), reconoce sinónimos y, ante la duda, elige el nivel más alto.
const b = $json.body || {};
const s = (v) => (v ?? '').toString().trim();

const paciente_nombre = s(b.paciente_nombre);
const documento_id = s(b.documento_id);
const email_paciente = s(b.email_paciente).toLowerCase();
const especialidad = s(b.especialidad);
const sintomas_desc = s(b.sintomas_desc);
const fecha_cita = s(b.fecha_cita);

const ESPECIALIDADES = ['Medicina General', 'Pediatría', 'Cardiología', 'Dermatología', 'Ortopedia', 'Ginecología'];
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());

const errores = [];
if (paciente_nombre.length < 3 || paciente_nombre.length > 120) errores.push('Nombre del paciente inválido');
if (!/^[0-9]{6,10}$/.test(documento_id)) errores.push('El documento debe tener entre 6 y 10 dígitos');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email_paciente)) errores.push('Correo electrónico inválido');
if (!ESPECIALIDADES.includes(especialidad)) errores.push('Especialidad no válida');
if (sintomas_desc.length < 10) errores.push('Describa los síntomas (mínimo 10 caracteres)');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha_cita) || fecha_cita < hoy) errores.push('La fecha no puede ser anterior a hoy');

// ---------- Clasificación ----------
// Frases ya normalizadas: minúsculas y sin tildes.
const ALTA = [
  'dolor en el pecho', 'dolor de pecho', 'dolor toracico', 'me duele el pecho', 'duele el pecho',
  'opresion en el pecho', 'opresion toracica', 'presion en el pecho', 'peso en el pecho',
  'falta de aire', 'me falta el aire', 'me falta aire', 'falta el aire',
  'dificultad para respirar', 'dificultad al respirar', 'dificultad respiratoria',
  'no puedo respirar', 'no respira', 'no me deja respirar', 'me quedo sin aire',
  'ahogo', 'me ahogo', 'asfixia',
  'desmayo', 'desmayos', 'desmaye', 'me desmaye', 'desmayado', 'desmayada',
  'perdi el conocimiento', 'perdida de conocimiento', 'perdida de conciencia', 'inconsciente', 'no reacciona',
  'convulsion', 'convulsiones', 'convulsionando',
  'hemorragia', 'sangrado abundante', 'sangra mucho', 'vomito con sangre', 'vomitando sangre', 'sangre en el vomito',
  'paralisis', 'no puedo mover', 'no puedo hablar', 'dificultad para hablar', 'cara torcida', 'no siento el brazo',
  'confusion', 'labios morados', 'reaccion alergica grave',
  'infarto', 'derrame cerebral', 'ictus',
  'ideas suicidas', 'suicidio', 'suicidarme', 'quiero morirme',
];
// Frases que ya contienen su propia negación: no se les aplica el filtro de negaciones.
const FUERTES = new Set([
  'no puedo respirar', 'no respira', 'no me deja respirar', 'me quedo sin aire',
  'no reacciona', 'no puedo mover', 'no puedo hablar', 'no siento el brazo',
]);
const PRIORITARIA = [
  'fiebre', 'febril', 'temperatura alta', 'vomito', 'vomitos', 'vomitando', 'diarrea',
  'dolor intenso', 'dolor fuerte', 'mucho dolor', 'dolor insoportable', 'fractura', 'golpe', 'caida',
  'infeccion', 'mareo', 'mareos', 'embarazo', 'embarazada', 'dolor abdominal', 'quemadura', 'herida',
  'presion alta', 'migrana', 'deshidratacion', 'sangrado', 'hinchazon',
];
// Señales ambiguas: si no hay nada más claro, se sube a Prioritaria (ante la duda, el nivel más alto).
const SOSPECHOSAS = ['pecho', 'respirar', 'respiracion', 'palpitaciones', 'sangre', 'corazon', 'desvanecimiento'];

const NEG = new Set(['no', 'sin', 'nunca', 'jamas', 'ni', 'ningun', 'ninguna', 'ninguno', 'tampoco', 'niego', 'descarto', 'ausencia', 'nada']);
const STOP = new Set(['y', 'e', 'pero', 'aunque', 'porque', 'por', 'con', 'debido', 'cuando', 'que', 'pues', 'sino']);
const DUDA = /(tal vez|quizas?|no estoy segur[oa]|no se si|a veces|creo que|me parece|podria ser|posible|dudo)/;

const texto = sintomas_desc.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const clausulas = texto
  .split(/[.,;:!?\n()\/]+|\s+(?:pero|aunque|sin embargo)\s+/)
  .map((c) => ' ' + c.replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim() + ' ')
  .filter((c) => c.trim().length > 0);

const posiciones = (c, kw) => {
  const r = [];
  let i = c.indexOf(' ' + kw + ' ');
  while (i !== -1) { r.push(i + 1); i = c.indexOf(' ' + kw + ' ', i + 1); }
  return r;
};

// Una negación afecta a la frase si aparece hasta 3 palabras antes, sin conjunciones ni preposiciones de por medio.
const estaNegada = (c, idx, duda) => {
  if (duda) return false;
  const prev = c.slice(0, idx).trim().split(' ').filter(Boolean);
  for (let j = prev.length - 1, n = 0; j >= 0 && n < 3; j--, n++) {
    if (STOP.has(prev[j])) return false;
    if (NEG.has(prev[j])) return true;
  }
  return false;
};

const detectar = (lista, cls) => {
  const hallazgos = [];
  const ignoradas = [];
  for (const c of cls) {
    const duda = DUDA.test(c);
    for (const kw of lista) {
      for (const idx of posiciones(c, kw)) {
        if (!FUERTES.has(kw) && estaNegada(c, idx, duda)) ignoradas.push(kw);
        else hallazgos.push(kw);
      }
    }
  }
  return { hallazgos, ignoradas };
};

const alta = detectar(ALTA, clausulas);
const prio = detectar(PRIORITARIA, clausulas);

// Las frases ya evaluadas (negadas o no) se enmascaran para que sus palabras sueltas
// (p. ej. "pecho" dentro de "no tengo dolor en el pecho") no se vuelvan a contar como señal ambigua.
const conocidas = [...ALTA, ...PRIORITARIA].sort((a, b) => b.length - a.length);
const enmascaradas = clausulas.map((c) => {
  let m = c;
  for (const kw of conocidas) while (m.includes(' ' + kw + ' ')) m = m.replace(' ' + kw + ' ', ' # ');
  return m;
});
const sosp = detectar(SOSPECHOSAS, enmascaradas);

let nivel_urgencia = 'Consulta General';
let senales = [];
if (alta.hallazgos.length) { nivel_urgencia = 'Urgencia Alta'; senales = alta.hallazgos; }
else if (prio.hallazgos.length) { nivel_urgencia = 'Prioritaria'; senales = prio.hallazgos; }
else if (sosp.hallazgos.length) { nivel_urgencia = 'Prioritaria'; senales = sosp.hallazgos; }

const senales_ignoradas = [...alta.ignoradas, ...prio.ignoradas, ...sosp.ignoradas];

return { json: {
  valido: errores.length === 0, errores,
  paciente_nombre, documento_id, email_paciente, especialidad, sintomas_desc, fecha_cita,
  nivel_urgencia,
  senales: [...new Set(senales)],
  senales_ignoradas: [...new Set(senales_ignoradas)],
} };

// Une el registro guardado (codigo_cita) con las recomendaciones de la ruta ejecutada
// y escapa el nombre del paciente para que no se interprete como HTML en el correo.
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const rutas = ['Ruta Urgencia Alta', 'Ruta Prioritaria', 'Ruta Consulta General'];
const ruta = rutas.find((n) => $(n).isExecuted);
const ctx = ruta ? $(ruta).item.json : {};
const row = $json;

return {
  json: {
    codigo_cita: row.codigo_cita,
    paciente_nombre: esc(row.paciente_nombre),
    email_paciente: row.email_paciente,
    especialidad: row.especialidad,
    fecha_cita: row.fecha_cita,
    nivel_urgencia: row.nivel_urgencia,
    estado: row.estado,
    recomendaciones: ctx.recomendaciones || '',
    asunto: ctx.asunto || `MediTurno - Cita ${row.codigo_cita}`,
    color: ctx.color || '#2563eb',
  },
};
